//! 🧪️ Native fixed rows retain original paths under one finite public-port work bank.
use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[test]
fn native_path_rows_are_cold_and_granted_with_original_custody_and_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🎟️original/payload.json")).unwrap();let rows=&law["rows"];let stock=&law["source"];
 for length in rows["lengths"].as_array().unwrap(){let length=length.as_u64().unwrap()as usize;let(mut paths,heap)=observe(NativePathSet::new);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut cpu=stock["fuel"].as_u64().unwrap();let mut items=stock["grant"]["maximumItems"].as_u64().unwrap()as usize;let mut copy=stock["grant"]["maximumCopyBytes"].as_u64().unwrap()as usize;let mut release=stock["grant"]["maximumReleaseBytes"].as_u64().unwrap()as usize;
  for index in 0..length{let mut input=Some(std::path::PathBuf::from(format!("original-path-{index}")));let pointer=input.as_ref().unwrap().as_os_str().as_encoded_bytes().as_ptr();let d=NativePathSet::push_demand();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};
   for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),d.copy_bytes.checked_sub(1).map(|copy|RetainedCloneGrant{maximum_copy_bytes:copy,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g})].into_iter().flatten(){let(turn,heap)=observe(||paths.push_from(&mut input,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(input.as_ref().unwrap().as_os_str().as_encoded_bytes().as_ptr(),pointer)}
   let(turn,heap)=observe(||paths.push_from(&mut input,g));assert_eq!(turn.work,1);assert!(turn.work<=cpu);cpu-=turn.work;let p=turn.result.unwrap().progress();assert!(p.copied_items<=items);items-=p.copied_items;assert!(p.copied_bytes<=copy);copy-=p.copied_bytes;assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(input.is_none());assert_eq!(paths.as_slice()[index].as_os_str().as_encoded_bytes().as_ptr(),pointer);assert_eq!(serde_json::to_value(paths.as_slice()[index].to_str().unwrap()).unwrap(),serde_json::json!(format!("original-path-{index}")));
  }
  if length==256{let mut input=Some(std::path::PathBuf::from("original-overflow"));let pointer=input.as_ref().unwrap().as_os_str().as_encoded_bytes().as_ptr();let turn=paths.push_from(&mut input,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_depth:64,..Default::default()});assert_eq!(turn.work,0);assert!(turn.result.is_err());assert_eq!(input.as_ref().unwrap().as_os_str().as_encoded_bytes().as_ptr(),pointer);}
  for at in 0..law["maximumTurns"].as_u64().unwrap(){if paths.is_empty(){break}let d=paths.close_demand();assert!(d.release_bytes<=release);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..Default::default()};
   for axis in rows["deniedAxes"].as_array().unwrap(){let amount=match axis.as_str().unwrap(){"items"=>1,"copy"=>d.copy_bytes,"release"=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut denied=g;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy"=>denied.maximum_copy_bytes=amount-1,"release"=>denied.maximum_release_bytes=amount-1,_=>denied.maximum_depth=amount-1};let(turn,heap)=observe(||paths.close_step(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
   let(turn,heap)=observe(||paths.close_step(g));assert_eq!(turn.work,1);assert!(turn.work<=cpu);cpu-=turn.work;let p=turn.result.unwrap().progress();assert!(p.copied_items<=items);items-=p.copied_items;assert!(p.released_bytes<=release);release-=p.released_bytes;assert_eq!((heap.requested_bytes,heap.released_bytes),(0,p.released_bytes));assert!(at<16383)
  }
  assert!(paths.is_empty());let(turn,heap)=observe(||paths.close_step(Default::default()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(cpu<=stock["fuel"].as_u64().unwrap());assert_eq!(observe(||drop(paths)).1.released_bytes,0);
 }
}
